// Android: make the game data readable by the game.
//
// The game reads its data with plain fopen()/chdir() relative to the data
// directory (see Sys::chdir_to_game_dir), so the files packaged as APK assets
// are copied to internal storage once, and SKDATA is pointed there. The APK
// carries a manifest (7kaa_assets.txt, generated by app/build.gradle) whose
// first line is a hash of all the data; the copy is redone only when it
// differs from the one stored next to the extracted files.

#include <android/log.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <string>
#include <vector>

#include "android_glue.h"

#define LOG_TAG "7kaa"
#define LOGI(...) __android_log_print(ANDROID_LOG_INFO, LOG_TAG, __VA_ARGS__)
#define LOGE(...) __android_log_print(ANDROID_LOG_ERROR, LOG_TAG, __VA_ARGS__)

static const char MANIFEST_ASSET[] = "7kaa_assets.txt";
static const char STAMP_FILE[] = ".assets_stamp";

static bool read_asset(const char *name, std::string &out)
{
	SDL_RWops *rw = SDL_RWFromFile(name, "rb");
	if( !rw )
		return false;
	out.clear();
	char buf[16384];
	size_t n;
	while( (n = SDL_RWread(rw, buf, 1, sizeof(buf))) > 0 )
		out.append(buf, n);
	SDL_RWclose(rw);
	return true;
}

static bool read_file(const std::string &path, std::string &out)
{
	FILE *f = fopen(path.c_str(), "rb");
	if( !f )
		return false;
	out.clear();
	char buf[4096];
	size_t n;
	while( (n = fread(buf, 1, sizeof(buf), f)) > 0 )
		out.append(buf, n);
	fclose(f);
	return true;
}

static bool write_file(const std::string &path, const std::string &data)
{
	FILE *f = fopen(path.c_str(), "wb");
	if( !f )
		return false;
	bool ok = fwrite(data.data(), 1, data.size(), f) == data.size();
	return (fclose(f) == 0) && ok;
}

static bool make_dirs(const std::string &path)
{
	for( size_t i = 1; i <= path.size(); i++ )
	{
		if( i == path.size() || path[i] == '/' )
		{
			std::string sub = path.substr(0, i);
			if( mkdir(sub.c_str(), 0755) != 0 && errno != EEXIST )
			{
				LOGE("mkdir %s failed: %s", sub.c_str(), strerror(errno));
				return false;
			}
		}
	}
	return true;
}

static bool copy_asset(const std::string &rel, const std::string &dest, std::vector<char> &buf)
{
	SDL_RWops *in = SDL_RWFromFile(rel.c_str(), "rb");
	if( !in )
	{
		LOGE("cannot open asset %s: %s", rel.c_str(), SDL_GetError());
		return false;
	}
	std::string tmp = dest + ".part";
	FILE *out = fopen(tmp.c_str(), "wb");
	if( !out )
	{
		LOGE("cannot create %s: %s", tmp.c_str(), strerror(errno));
		SDL_RWclose(in);
		return false;
	}
	bool ok = true;
	size_t n;
	while( (n = SDL_RWread(in, buf.data(), 1, buf.size())) > 0 )
	{
		if( fwrite(buf.data(), 1, n, out) != n )
		{
			ok = false;
			break;
		}
	}
	SDL_RWclose(in);
	if( fclose(out) != 0 )
		ok = false;
	if( ok && rename(tmp.c_str(), dest.c_str()) != 0 )
		ok = false;
	if( !ok )
	{
		LOGE("writing %s failed: %s", dest.c_str(), strerror(errno));
		remove(tmp.c_str());
	}
	return ok;
}

static void fail(const char *msg)
{
	LOGE("%s", msg);
	SDL_ShowSimpleMessageBox(SDL_MESSAGEBOX_ERROR, "Seven Kingdoms", msg, NULL);
}

int android_prepare_game_data()
{
	// Touch input is translated by android_touch.cpp; do not let SDL turn
	// fingers into mouse clicks as well.
	SDL_SetHint(SDL_HINT_TOUCH_MOUSE_EVENTS, "0");
	// ...and do not turn a real mouse into fake touches either.
	SDL_SetHint(SDL_HINT_MOUSE_TOUCH_EVENTS, "0");
	// Deliver the Back button to the game (mapped to Esc) instead of quitting.
	SDL_SetHint(SDL_HINT_ANDROID_TRAP_BACK_BUTTON, "1");
	SDL_SetHint(SDL_HINT_ORIENTATIONS, "LandscapeLeft LandscapeRight");

	const char *internal = SDL_AndroidGetInternalStoragePath();
	if( !internal )
	{
		fail("Cannot access the app's internal storage.");
		return 0;
	}
	std::string data_dir = std::string(internal) + "/gamedata/";

	std::string manifest;
	if( !read_asset(MANIFEST_ASSET, manifest) )
	{
		fail("The game data is missing from this APK.");
		return 0;
	}

	size_t eol = manifest.find('\n');
	std::string stamp = manifest.substr(0, eol);
	std::string old_stamp;
	read_file(data_dir + STAMP_FILE, old_stamp);

	if( stamp != old_stamp )
	{
		LOGI("Extracting game data to %s", data_dir.c_str());
		Uint32 start = SDL_GetTicks();
		if( !make_dirs(data_dir) )
		{
			fail("Cannot create the game data folder.");
			return 0;
		}
		remove((data_dir + STAMP_FILE).c_str());

		std::vector<char> buf(256 * 1024);
		int count = 0;
		size_t pos = (eol == std::string::npos) ? manifest.size() : eol + 1;
		while( pos < manifest.size() )
		{
			size_t end = manifest.find('\n', pos);
			if( end == std::string::npos )
				end = manifest.size();
			std::string line = manifest.substr(pos, end - pos);
			pos = end + 1;
			if( !line.empty() && line[line.size()-1] == '\r' )
				line.erase(line.size()-1);
			if( line.empty() )
				continue;

			// "<size> <relative path>"
			size_t sp = line.find(' ');
			if( sp == std::string::npos )
				continue;
			std::string rel = line.substr(sp + 1);
			std::string dest = data_dir + rel;
			size_t slash = dest.rfind('/');
			if( slash != std::string::npos && !make_dirs(dest.substr(0, slash)) )
			{
				fail("Cannot create the game data folder.");
				return 0;
			}
			if( !copy_asset(rel, dest, buf) )
			{
				fail("Unpacking the game data failed. Is the device storage full?");
				return 0;
			}
			count++;
		}

		if( !write_file(data_dir + STAMP_FILE, stamp) )
			LOGE("cannot write data stamp");
		LOGI("Extracted %d files in %u ms", count, (unsigned)(SDL_GetTicks() - start));
	}

	setenv("SKDATA", data_dir.c_str(), 1);
	return 1;
}
